using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS",   Name = "Computer Science",       Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics",            Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Code = "PHYS", Name = "Physics",                Description = "Exploration of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG",  Name = "English",                Description = "Literature, writing, rhetoric, and critical analysis." },
            new() { Id = 5, Code = "HIST", Name = "History",                Description = "Examination of human civilizations, events, and cultural change." },
            new() { Id = 6, Code = "BIOL", Name = "Biology",                Description = "The science of life, organisms, genetics, and ecosystems." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen",      Title = "Professor",           Email = "achen@university.edu",     Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 40 peer-reviewed papers and holds two patents in fault-tolerant architectures." },
            new() { Id = 2, Name = "Dr. Robert Müller",    Title = "Associate Professor", Email = "rmuller@university.edu",   Bio = "Dr. Müller's research focuses on algebraic topology and its applications in data science. He received the departmental teaching excellence award in 2023." },
            new() { Id = 3, Name = "Dr. Priya Sharma",     Title = "Professor",           Email = "psharma@university.edu",   Bio = "Dr. Sharma is a leading researcher in quantum optics with 15 years of experience. She directs the university's Photonics Research Laboratory." },
            new() { Id = 4, Name = "Dr. James Okafor",     Title = "Senior Lecturer",     Email = "jokafor@university.edu",   Bio = "Dr. Okafor is a published novelist and literary critic whose work examines post-colonial narratives. He has taught creative writing workshops across four continents." },
            new() { Id = 5, Name = "Dr. Maria González",   Title = "Professor",           Email = "mgonzalez@university.edu", Bio = "Dr. González is a historian of early-modern Latin America. Her latest book explores trade networks in the colonial Caribbean." },
            new() { Id = 6, Name = "Dr. Samuel Park",      Title = "Assistant Professor", Email = "spark@university.edu",     Bio = "Dr. Park studies molecular genetics and CRISPR gene-editing techniques. He joined the faculty after a postdoc at the National Institutes of Health." },
            new() { Id = 7, Name = "Dr. Emily Thornton",   Title = "Associate Professor", Email = "ethornton@university.edu", Bio = "Dr. Thornton researches machine learning and natural language processing. She leads the AI for Social Good initiative at the university." },
            new() { Id = 8, Name = "Dr. Kenji Watanabe",   Title = "Professor",           Email = "kwatanabe@university.edu", Bio = "Dr. Watanabe is an expert in partial differential equations and mathematical modeling. He has mentored over 20 PhD students." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1,  Code = "CS 101",   Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering problem-solving, basic programming in Python, data representation, and an overview of modern computing topics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",   Room = "Science Hall 201",   DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2,  Code = "CS 201",   Title = "Data Structures & Algorithms",     Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and complexity analysis.",                Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM",    Room = "Science Hall 305",   DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3,  Code = "CS 350",   Title = "Machine Learning Fundamentals",     Description = "An introduction to supervised and unsupervised learning, neural networks, and model evaluation. Students complete hands-on projects with real-world datasets.",                 Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM",       Room = "Tech Center 110",    DepartmentId = 1, InstructorId = 7, IsFeatured = true },

            // Mathematics
            new() { Id = 4,  Code = "MATH 101", Title = "Calculus I",                        Description = "Limits, derivatives, and integrals of single-variable functions with applications in science and engineering.",                                                               Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM",  Room = "Math Building 101",  DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5,  Code = "MATH 240", Title = "Linear Algebra",                    Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Emphasizes both theory and computational methods.",                                            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM",       Room = "Math Building 203",  DepartmentId = 2, InstructorId = 8, IsFeatured = true },
            new() { Id = 6,  Code = "MATH 310", Title = "Probability & Statistics",          Description = "Combinatorics, probability distributions, hypothesis testing, regression, and Bayesian inference with examples from the natural and social sciences.",                         Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Math Building 105",  DepartmentId = 2, InstructorId = 2 },

            // Physics
            new() { Id = 7,  Code = "PHYS 101", Title = "General Physics I",                 Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.",                                                                        Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM",      Room = "Physics Lab 100",    DepartmentId = 3, InstructorId = 3 },
            new() { Id = 8,  Code = "PHYS 250", Title = "Quantum Mechanics",                 Description = "Introduction to wave-particle duality, the Schrödinger equation, quantum states, and measurement theory.",                                                                    Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM",       Room = "Physics Lab 210",    DepartmentId = 3, InstructorId = 3, IsFeatured = true },

            // English
            new() { Id = 9,  Code = "ENG 101",  Title = "Composition & Rhetoric",            Description = "Develop critical reading, analytical writing, and argumentation skills through essays, peer review, and revision workshops.",                                                  Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM",   Room = "Humanities 302",     DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "ENG 220",  Title = "World Literature",                  Description = "A survey of literary masterpieces from diverse cultures and time periods, exploring themes of identity, power, and transformation.",                                            Credits = 3, Schedule = "Tue/Thu 11:30 AM–12:45 PM",  Room = "Humanities 115",     DepartmentId = 4, InstructorId = 4 },

            // History
            new() { Id = 11, Code = "HIST 101", Title = "World History to 1500",             Description = "Major civilizations, trade routes, religions, and political systems from antiquity through the late medieval period.",                                                          Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM",       Room = "Liberal Arts 400",   DepartmentId = 5, InstructorId = 5 },
            new() { Id = 12, Code = "HIST 205", Title = "Modern Latin American History",     Description = "Colonial legacies, independence movements, revolutions, and contemporary politics in Latin America from the 18th century to the present.",                                      Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM",     Room = "Liberal Arts 212",   DepartmentId = 5, InstructorId = 5, IsFeatured = true },

            // Biology
            new() { Id = 13, Code = "BIOL 101", Title = "Introduction to Biology",           Description = "Cell structure, genetics, evolution, and ecology. Includes lab sessions on microscopy and molecular biology techniques.",                                                      Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM",   Room = "Life Sciences 101",  DepartmentId = 6, InstructorId = 6 },
            new() { Id = 14, Code = "BIOL 320", Title = "Molecular Genetics",                Description = "Gene expression, regulation, CRISPR technology, and genomic analysis. Requires a background in introductory biology and chemistry.",                                           Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM",       Room = "Life Sciences 310",  DepartmentId = 6, InstructorId = 6, IsFeatured = true },
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Instructor> GetInstructors() => _instructors;

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public IReadOnlyList<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
