@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero">
    <h1>University Course Catalog</h1>
    <p>Explore departments, discover courses, and enroll for the upcoming semester.</p>
    <div class="hero-actions">
        <a href="/courses" class="btn btn-primary">Browse All Courses</a>
        <a href="/enroll" class="btn btn-secondary">Enroll Now</a>
    </div>
</div>

<section class="section">
    <h2>Featured Courses</h2>
    <div class="card-grid">
        @foreach (var course in featuredCourses)
        {
            var dept = Catalog.GetDepartment(course.DepartmentId);
            <a href="/courses/@course.Id" class="card">
                <span class="card-badge">@dept?.Code</span>
                <h3>@course.Code — @course.Title</h3>
                <p>@course.Credits credits · @course.Schedule</p>
            </a>
        }
    </div>
</section>

<section class="section">
    <h2>Departments</h2>
    <div class="card-grid">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="card">
                <span class="card-badge">@dept.Code</span>
                <h3>@dept.Name</h3>
                <p>@dept.Description</p>
            </a>
        }
    </div>
</section>

