@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1>Courses</h1>

<form method="get" class="search-bar">
    <input type="text" name="q" value="@Query" placeholder="Search by title, code, or keyword…" />
    <select name="departmentId">
        <option value="">All Departments</option>
        @foreach (var dept in departments)
        {
            if (dept.Id == DepartmentId)
            {
                <option value="@dept.Id" selected>@dept.Name</option>
            }
            else
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        }
    </select>
    <button type="submit" class="btn btn-primary">Search</button>
</form>

@if (courses.Count == 0)
{
    <p class="empty-state">No courses found. Try adjusting your search or filter.</p>
}
else
{
    <table class="data-table">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = Catalog.GetDepartment(course.DepartmentId);
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="/courses/@course.Id" class="btn btn-small">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery(Name = "q")]
    public string? Query { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<Department> departments = [];
    private IReadOnlyList<Course> courses = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.SearchCourses(Query, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist. <a href="/courses">Back to all courses</a></p>
}
else
{
    <PageTitle>@course.Code — University Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> ›
        <a href="/courses?departmentId=@department?.Id">@department?.Name</a> ›
        <span>@course.Code</span>
    </nav>

    <div class="detail-header">
        <h1>@course.Code — @course.Title</h1>
        <a href="/enroll?courseId=@course.Id" class="btn btn-primary">Enroll in This Course</a>
    </div>

    <div class="detail-grid">
        <div class="detail-main">
            <h2>Description</h2>
            <p>@course.Description</p>
        </div>

        <aside class="detail-sidebar">
            <div class="info-card">
                <h3>Details</h3>
                <dl>
                    <dt>Credits</dt>
                    <dd>@course.Credits</dd>
                    <dt>Schedule</dt>
                    <dd>@course.Schedule</dd>
                    <dt>Room</dt>
                    <dd>@course.Room</dd>
                    <dt>Department</dt>
                    <dd>@department?.Name</dd>
                </dl>
            </div>

            @if (instructor is not null)
            {
                <div class="info-card">
                    <h3>Instructor</h3>
                    <p class="instructor-name">@instructor.Name</p>
                    <p class="instructor-title">@instructor.Title</p>
                    <p>@instructor.Bio</p>
                    <p><a href="mailto:@instructor.Email">@instructor.Email</a></p>
                </div>
            }
        </aside>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            department = Catalog.GetDepartment(course.DepartmentId);
            instructor = Catalog.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enroll — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>Request Submitted</h2>
        <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(model.CourseId)?.Title)</strong> has been received.
            You will be notified by email once it is processed.</p>
        <a href="/courses" class="btn btn-primary">Back to Courses</a>
    </div>
}
else
{
    <form method="post" @formname="enrollment" @onsubmit="HandleSubmit" class="enrollment-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input id="studentName" name="model.StudentName" value="@model.StudentName" required />
            <ValidationMessage For="() => model.StudentName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input id="studentId" name="model.StudentId" value="@model.StudentId"
                   placeholder="e.g. CS12345" required />
            <ValidationMessage For="() => model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="model.CourseId" required>
                <option value="">— Select a course —</option>
                @foreach (var course in allCourses)
                {
                    if (course.Id == model.CourseId)
                    {
                        <option value="@course.Id" selected>@course.Code — @course.Title</option>
                    }
                    else
                    {
                        <option value="@course.Id">@course.Code — @course.Title</option>
                    }
                }
            </select>
            <ValidationMessage For="() => model.CourseId" />
        </div>

        <div class="form-group">
            <label for="comments">Comments (optional)</label>
            <textarea id="comments" name="model.Comments" rows="3">@model.Comments</textarea>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<Course> allCourses = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        allCourses = Catalog.GetAllCourses();

        if (CourseId.HasValue && model.CourseId == 0)
            model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollment(model);
        submitted = true;
    }
}

