/* ===== Base Reset & Typography ===== */
*, *::before, *::after { box-sizing: border-box; }

html, body {
    margin: 0;
    padding: 0;
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    color: #1e293b;
    background: #f8fafc;
    line-height: 1.6;
}

a { color: #1d4ed8; text-decoration: none; }
a:hover { text-decoration: underline; }

h1, h2, h3 { margin-top: 0; color: #0f172a; }

/* ===== Layout Shell ===== */
.site-wrapper {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.site-content {
    flex: 1;
    max-width: 1100px;
    width: 100%;
    margin: 0 auto;
    padding: 2rem 1.5rem;
}

/* ===== Header ===== */
.site-header {
    background: #1e3a5f;
    color: #fff;
    padding: 0 1.5rem;
}

.header-inner {
    max-width: 1100px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 60px;
}

.site-brand {
    color: #fff;
    font-size: 1.25rem;
    font-weight: 700;
    text-decoration: none;
}

.site-nav { display: flex; gap: 1.5rem; }
.site-nav a { color: #cbd5e1; font-weight: 500; }
.site-nav a:hover, .site-nav a.active { color: #fff; text-decoration: none; }

/* ===== Footer ===== */
.site-footer {
    background: #1e293b;
    color: #94a3b8;
    text-align: center;
    padding: 1.25rem;
    font-size: 0.875rem;
}

/* ===== Hero ===== */
.hero {
    background: linear-gradient(135deg, #1e3a5f, #2563eb);
    color: #fff;
    border-radius: 12px;
    padding: 3rem 2.5rem;
    margin-bottom: 2.5rem;
    text-align: center;
}

.hero h1 { font-size: 2.25rem; margin-bottom: 0.5rem; color: #fff; }
.hero p { font-size: 1.15rem; opacity: 0.9; margin-bottom: 1.5rem; }
.hero-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

/* ===== Buttons ===== */
.btn {
    display: inline-block;
    padding: 0.6rem 1.4rem;
    border-radius: 6px;
    font-weight: 600;
    font-size: 0.95rem;
    border: none;
    cursor: pointer;
    text-decoration: none;
    transition: background 0.15s;
}

.btn-primary { background: #2563eb; color: #fff; }
.btn-primary:hover { background: #1d4ed8; text-decoration: none; color: #fff; }

.btn-secondary { background: rgba(255,255,255,0.2); color: #fff; border: 1px solid rgba(255,255,255,0.4); }
.btn-secondary:hover { background: rgba(255,255,255,0.3); text-decoration: none; color: #fff; }

.btn-small { padding: 0.3rem 0.8rem; font-size: 0.85rem; }

/* ===== Section ===== */
.section { margin-bottom: 2.5rem; }
.section h2 { font-size: 1.5rem; margin-bottom: 1rem; padding-bottom: 0.4rem; border-bottom: 2px solid #e2e8f0; }

/* ===== Card Grid ===== */
.card-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1.25rem;
}

.card {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 1.5rem;
    transition: box-shadow 0.15s, border-color 0.15s;
    color: inherit;
    text-decoration: none;
    display: block;
}

.card:hover {
    border-color: #2563eb;
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.12);
    text-decoration: none;
}

.card h3 { font-size: 1.1rem; margin: 0.5rem 0 0.4rem; }
.card p { margin: 0; color: #64748b; font-size: 0.9rem; }

.card-badge {
    display: inline-block;
    background: #eff6ff;
    color: #1d4ed8;
    font-weight: 700;
    font-size: 0.8rem;
    padding: 0.15rem 0.6rem;
    border-radius: 4px;
}

/* ===== Search Bar ===== */
.search-bar {
    display: flex;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
    flex-wrap: wrap;
}

.search-bar input[type="text"],
.search-bar select {
    padding: 0.55rem 0.9rem;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font-size: 0.95rem;
    background: #fff;
}

.search-bar input[type="text"] { flex: 1; min-width: 200px; }
.search-bar select { min-width: 180px; }

.empty-state {
    text-align: center;
    padding: 3rem 1rem;
    color: #64748b;
    font-size: 1.1rem;
}

/* ===== Data Table ===== */
.data-table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid #e2e8f0;
}

.data-table th, .data-table td {
    padding: 0.75rem 1rem;
    text-align: left;
}

.data-table thead { background: #f1f5f9; }
.data-table th { font-weight: 600; font-size: 0.85rem; text-transform: uppercase; color: #475569; letter-spacing: 0.03em; }
.data-table tbody tr { border-top: 1px solid #e2e8f0; }
.data-table tbody tr:hover { background: #f8fafc; }

/* ===== Course Detail ===== */
.breadcrumb {
    font-size: 0.9rem;
    color: #64748b;
    margin-bottom: 1rem;
}

.breadcrumb a { color: #2563eb; }
.breadcrumb span { color: #1e293b; }

.detail-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 2rem;
}

.detail-header h1 { margin: 0; }

.detail-grid {
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 2rem;
}

.detail-main p { font-size: 1.05rem; line-height: 1.7; color: #334155; }

.info-card {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 1.5rem;
    margin-bottom: 1.25rem;
}

.info-card h3 { font-size: 1rem; margin-bottom: 0.75rem; color: #1e3a5f; }

.info-card dl { margin: 0; }
.info-card dt { font-weight: 600; font-size: 0.85rem; color: #64748b; text-transform: uppercase; margin-top: 0.6rem; }
.info-card dd { margin: 0.1rem 0 0; }

.instructor-name { font-weight: 700; margin-bottom: 0; }
.instructor-title { color: #64748b; margin-top: 0; font-size: 0.9rem; }

/* ===== Enrollment Form ===== */
.enrollment-form {
    max-width: 560px;
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
    font-size: 0.95rem;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: 0.55rem 0.9rem;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font-size: 0.95rem;
    font-family: inherit;
}

.form-group textarea { resize: vertical; }

.success-message {
    background: #ecfdf5;
    border: 1px solid #6ee7b7;
    border-radius: 10px;
    padding: 2rem;
    max-width: 560px;
}

.success-message h2 { color: #065f46; }

/* ===== Validation ===== */
.validation-message { color: #dc2626; font-size: 0.85rem; margin-top: 0.25rem; }

/* ===== Responsive ===== */
@media (max-width: 768px) {
    .detail-grid { grid-template-columns: 1fr; }
    .hero { padding: 2rem 1.5rem; }
    .hero h1 { font-size: 1.75rem; }
    .data-table { font-size: 0.9rem; }
    .data-table th, .data-table td { padding: 0.5rem 0.6rem; }
}

/* ===== Blazor defaults ===== */
.blazor-error-boundary {
    background: url(data:image/svg+xml;base64,) no-repeat 1rem/1.8rem, #b32121;
    padding: 1rem 1rem 1rem 3.7rem;
    color: white;
}

